/**
 * Fifty expedition archetypes: Chalkfold is an unchanged legacy reference;
 * forty-nine authored journeys replace the frontier's repeated cave loop.
 * Selection uses a private hash stream and never changes a galaxy or its RNG.
 */
const freeze = value => { if (value && typeof value === 'object') { for (const child of Object.values(value)) freeze(child); Object.freeze(value); } return value; };
const clone = value => JSON.parse(JSON.stringify(value));
const hash = value => { let h = 2166136261; for (const char of String(value)) h = Math.imul(h ^ char.charCodeAt(0), 16777619); return h >>> 0; };
const reward = (credits = 0, ore = 0, crystal = 0, heal = 0) => ({ credits, ore, crystal, heal });
const R = (id, name, text, gates = {}) => ({ id, name, text, ...gates });
const O = (id, label, text, payment = reward(), effects = {}) => ({ id, label, text, reward: payment, effects });
const C = (id, name, text, options, gates = {}) => ({ id, name, text, options, ...gates });
const P = (id, name, text, options, solution, completeText, gates = {}, effects = {}, payment = reward(90)) => ({
  id, name, text, options: options.map(([id, label]) => ({ id, label })), ...gates,
  puzzle: { solution, reward: payment, text: completeText, effects, wrongText: 'The interlock returns to its starting state. Check the posted evidence and try the sequence again.' }
});
const S = (id, name, species, roleLabel, text, role = 'settler') => ({ id, name, species, role, roleLabel, text, greeting: text });
const H = (id, name, species, combatProfile, tileX, tileY, extra = {}) => ({ id, name, species, combatProfile, profile: combatProfile, tileX, tileY, hostileToPlayer: true, hostileTo: [], ...extra });
const squad = (factionId, opponents, species, side = 0) => [
  H(`${factionId}-rifle`, `${factionId === 'freewake' ? 'Union' : factionId === 'meridian' ? 'Combine' : 'Clan'} rifle guard`, species, 'faction-rifle', side ? 37 : 17, side ? 13 : 11, { factionId, team: factionId, hostileToPlayer: false, hostileTo: opponents }),
  H(`${factionId}-support`, `${factionId === 'freewake' ? 'Union' : factionId === 'meridian' ? 'Combine' : 'Clan'} support guard`, 'human', 'faction-support', side ? 38 : 15, side ? 21 : 20, { factionId, team: factionId, hostileToPlayer: false, hostileTo: opponents })
];
const REP = (values, aftermath, other = {}) => ({ rep: values, aftermath, ...other });

