const recordPositions = [[14, 10], [26, 8], [38, 13], [10, 18]];
const choicePositions = [[9, 25], [23, 25], [35, 26], [34, 19]];
const residentPositions = [[8, 28], [11, 27], [16, 26], [19, 28]];
const locate = (items, positions) => (items || []).map((item, index) => ({ ...item, x: item.x ?? positions[index % positions.length][0], y: item.y ?? positions[index % positions.length][1] }));
const compile = story => {
  const outdoors = story.outdoors ?? (!['powerplant', 'observatory'].includes(story.layout) && !(story.layout === 'creature-nest' && story.kind === 'cave'));
  return { ...story, archetypeId: story.id, expedition: true, cols: 48, rows: 36, outdoors,
    biomes: [...new Set(story.biomes.map(biome => biomeOf({ biome })))],
    terrainBiome: story.terrainBiome || (!outdoors ? story.kind === 'cave' ? 'cave' : 'shelter' : undefined),
    atmosphere: story.atmosphere || (story.horror ? 'cave' : outdoors ? 'field' : 'shelter'),
    completionChoiceId: story.completionChoiceId || story.choices?.at(-1)?.id,
    selectionWeight: story.satire ? 2 : story.horror ? 1 : 10,
    records: locate(story.records, recordPositions), choices: locate(story.choices, choicePositions),
    caches: locate(story.caches, [[39, 29], [31, 17]]), residents: locate(story.residents, residentPositions), hostiles: story.hostiles || []
  };
};

const hearthCaverns = {
  id: 'hearth-chalkfold', archetypeId: 'hearth-chalkfold', name: 'Hearth caverns', kind: 'legacy', legacy: true,
  summary: 'The existing Hearth cave-expedition family, preserved exactly as authored.',
  story: 'Morrow’s Chalkfold Cavern and Tinbell’s hollow with the Bellwether retain their released maps, creatures, rewards and persistence rules.',
  legacyLocations: [{ bodyId: 'morrow', siteId: 'chalkfold' }, { bodyId: 'tinbell', siteId: 'hollow', bossId: 'bellwether' }],
  records: [], choices: [], caches: [], residents: [], hostiles: []
};

export const EXPEDITION_ARCHETYPES = freeze([hearthCaverns, ...stories.map(compile)]);
const byId = new Map(EXPEDITION_ARCHETYPES.map(archetype => [archetype.id, archetype]));
export const storyArchetypeById = id => byId.get(String(id || '').replace(/^story-/, '')) || null;

/** These existing worlds guarantee that every new scenario exists in the chart. */
export const EXPEDITION_SHOWCASES = freeze({
  chora: ['witness-archive', 'translation-hearing', 'echo-classroom'],
  avel: ['tidal-intake', 'divided-infirmary'],
  hadrun: ['courtyard-mediation', 'loadbearing-lesson'],
  orchard: ['migration-fence', 'mirror-orchard'],
  'kindred-landing': ['relief-bridge', 'prisoner-exchange'],
  cairn: ['courier-crash', 'salvage-memorial'],
  newshore: ['lichen-contract', 'pollinator-festival', 'spore-lexicon'],
  tessera: ['dust-checkpoint', 'venom-ledger'],
  tallow: ['recruitment-demo', 'weather-vermin'],
  luna: ['nightglass-listening'],
  ward: ['pressure-rescue', 'underice-hatch'],
  'voltage-reservoir': ['quarantine-pantry', 'aqueduct-siege'],
  wide: ['signal-choir', 'storm-market'],
  stillwater: ['mosaic-provenance', 'impact-inquest'],
  palimpsest: ['buried-armistice', 'dead-letter-route'],
  'brassfall-works': ['furnace-walkout', 'victory-rehearsal'],
  lilt: ['polyp-nursery', 'ferry-picket'],
  serein: ['salt-caravan', 'survey-crossfire', 'burrow-frontier'],
  'ochre-garden': ['firebreak-garden', 'root-council'],
  moth: ['avalanche-radio', 'broken-array'],
  'voltage-kilowatt': ['runaway-rail', 'mislabeled-cargo'],
  noonless: ['starlight-lens', 'thermal-refuge'],
  'low-water': ['empty-ward'],
  kiln: ['sleeping-foundry', 'grid-auction']
});

function biomeOf(body) {
  const biome = String(body?.biome || 'temperate');
  if (/ice|froz|snow/.test(biome)) return 'ice';
  if (/^(?:barren|rock|rocky|dust|dusty)(?:$|[-\s])/.test(biome) || body?.kind === 'asteroid') return 'barren';
  if (biome === 'arid') return 'desert';
  if (biome === 'earth') return 'temperate';
  return biome;
}
const excluded = body => !body || ['station', 'ship', 'derelict', 'site', 'blackhole'].includes(body.kind) || body.landable === false
  || body.systemId === 'hearth' || ['morrow', 'tinbell', 'glimmer', 'reedbank'].includes(body.id)
  || String(body.id || '').startsWith('crosswind-') || body.military === true || body.portType === 'military'
  || body.techLevel === 'preflight' || body.culture === 'reedbound';
export const canHaveExpeditionStories = body => !excluded(typeof body === 'string' ? { id: body } : body);

/** The old three entrance footprints remain exact, protecting authored towns. */
export function expeditionStoryEntrance(body, seed = 'farwake', slot = 0) {
  const bodyId = String(body?.id || 'world'), oldHash = hash(`${seed}:${bodyId}:expeditions`);
  const slots = [[68 + oldHash % 9, 16], [30 + oldHash % 8, 60], [87, 55]];
  const [tileX, tileY] = slots[Math.max(0, Math.min(2, Math.floor(slot)))];
  return { tileX, tileY, entrance: { x: (tileX + .5) * 24, y: (tileY + .5) * 24 } };
}

/** Public materializer also supports exhaustive layout and runtime validation. */
export function materializeExpeditionArchetype(archetypeOrId, body = {}, seed = 'farwake', slot = 0) {
  const archetype = typeof archetypeOrId === 'string' ? storyArchetypeById(archetypeOrId) : archetypeOrId;
  if (!archetype || archetype.legacy) return null;
  const data = clone(archetype), bodyId = String(body.id || 'world'), id = `story-${archetype.id}`, biome = biomeOf(body);
  const terrainBiome = data.terrainBiome || ({ forest: 'verdant', temperate: 'verdant', ocean: 'ocean', desert: 'arid', ice: 'ice', volcanic: 'volcanic' })[biome] || 'barren';
  return { ...data, id, archetypeId: archetype.id, bodyId, key: `${bodyId}:site:${id}`, ...expeditionStoryEntrance(body, seed, slot), terrainBiome,
    hostile: data.hostiles.some(actor => actor.hostileToPlayer !== false || actor.hostileTo?.length), monsterCount: data.hostiles.length, empty: false,
    residents: data.residents.map(person => ({ ...person, hostile: false, data: { ...person.data, expeditionResident: true, siteId: id, bodyId, species: person.species || 'human' } })),
    hostiles: data.hostiles.map(actor => ({ ...actor, id: actor.id, hostile: true, x: (actor.tileX + .5) * 24, y: (actor.tileY + .5) * 24 }))
  };
}

/** Two barren-world sites, three elsewhere; no new settlement footprint. */
export function expeditionStorySites(body = {}, seed = 'farwake') {
  if (typeof body === 'string') body = { id: body, name: body };
  if (excluded(body)) return [];
  // Retain the released footprint rule exactly (including industrial matching 'dust').
  // Content selection uses the actual industrial biome, independent of footprint count.
  const biome = biomeOf(body), count = /barren|rock|dust/.test(String(body.biome || '')) || body.kind === 'asteroid' ? 2 : 3, bodyId = String(body.id || 'world');
  const selected = (EXPEDITION_SHOWCASES[bodyId] || []).map(storyArchetypeById).filter(Boolean).slice(0, count);
  const used = new Set(selected.map(story => story.id));
  const pool = EXPEDITION_ARCHETYPES.filter(story => !story.legacy && (story.biomes.includes('any') || story.biomes.includes(biome)))
    .map(story => ({ story, score: hash(`${seed}:${bodyId}:expedition-story-v1:${story.id}`) / story.selectionWeight }))
    .sort((a, b) => a.score - b.score || a.story.id.localeCompare(b.story.id));
  for (const { story } of pool) { if (selected.length >= count) break; if (!used.has(story.id)) { selected.push(story); used.add(story.id); } }
  return selected.map((story, slot) => materializeExpeditionArchetype(story, body, seed, slot));
}
